-6">งาน</span></div></div></div></article></div></section>
<section class="mb-5" aria-labelledby="monitor-heading"><div class="mb-4"><h2 id="monitor-heading" class="page-heading h4 fw-bold mb-1">ติดตามกิจกรรมและความคืบหน้างาน</h2><p class="text-muted mb-0">ตัวกรองและพื้นที่วิดเจ็ตสำหรับการขยายข้อมูลในอนาคต</p></div><article class="card monitor-widget mb-4"><div class="card-header d-flex align-items-center gap-2 py-3 px-4"><span class="section-icon d-inline-flex align-items-center justify-content-center"><i class="bi bi-funnel"></i></span><h3 class="page-heading h5 fw-bold mb-0">ตัวกรองข้อมูล</h3></div><div class="card-body p-4"><div class="row g-3"><div class="col-sm-6 col-xl-3"><label class="form-label" for="monitorStartDate">วันที่เริ่มต้น</label><input class="form-control date-picker" id="monitorStartDate" type="text" placeholder="19/07/2569"></div><div class="col-sm-6 col-xl-3"><label class="form-label" for="monitorEndDate">วันที่สิ้นสุด</label><input class="form-control date-picker" id="monitorEndDate" type="text" placeholder="19/07/2569"></div><div class="col-sm-6 col-xl-2"><label class="form-label" for="monitorDepartment">แผนก</label><select class="form-select" id="monitorDepartment"><option selected>ทั้งหมด</option><?php foreach ($departments as $item): ?><option><?php echo htmlspecialchars($item, ENT_QUOTES, "UTF-8"); ?></option><?php endforeach; ?></select></div><div class="col-sm-6 col-xl-2"><label class="form-label" for="monitorStatus">สถานะ</label><select class="form-select" id="monitorStatus"><option selected>ทั้งหมด</option><?php foreach ($task_status_options as $item): ?><option><?php echo htmlspecialchars($item, ENT_QUOTES, "UTF-8"); ?></option><?php endforeach; ?></select></div><div class="col-sm-12 col-xl-2"><label class="form-label" for="monitorCategory">ประเภทปัญหา</label><select class="form-select" id="monitorCategory"><option selected>ทั้งหมด</option><?php foreach ($problem_category_options as $item): ?><option><?php echo htmlspecialchars($item, ENT_QUOTES, "UTF-8"); ?></option><?php endforeach; ?></select></div></div></div></article><div class="row g-4 mb-4"><div class="col-sm-6 col-xl"><article class="card monitor-widget h-100"><div class="card-body"><div class="widget-kpi-label">งานทั้งหมด</div><div class="widget-kpi-value fw-bold"><?php echo $dashboard_counts["total"]; ?> งาน</div></div></article></div><div class="col-sm-6 col-xl"><article class="card monitor-widget h-100"><div class="card-body"><div class="widget-kpi-label">รอดำเนินการ</div><div class="widget-kpi-value fw-bold"><?php echo $dashboard_counts["pending"]; ?> งาน</div></div></article></div><div class="col-sm-6 col-xl"><article class="card monitor-widget h-100"><div class="card-body"><div class="widget-kpi-label">กำลังดำเนินการ</div><div class="widget-kpi-value fw-bold"><?php echo $dashboard_counts["in_progress"]; ?> งาน</div></div></article></div><div class="col-sm-6 col-xl"><article class="card monitor-widget h-100"><div class="card-body"><div class="widget-kpi-label">เสร็จสิ้น</div><div class="widget-kpi-value fw-bold"><?php echo $dashboard_counts["completed"]; ?> งาน</div></div></article></div><div class="col-sm-6 col-xl"><article class="card monitor-widget h-100"><div class="card-body"><div class="widget-kpi-label">ยกเลิก</div><div class="widget-kpi-value fw-bold"><?php echo $dashboard_counts["cancelled"]; ?> งาน</div></div></article></div></div><div class="row g-4 mb-4"><div class="col-lg-6"><article class="card monitor-widget h-100"><div class="card-header py-3 px-4"><h3 class="page-heading h5 fw-bold mb-0">พื้นที่แผนภูมิ</h3></div><div class="card-body"><div class="chart-placeholder"><div><i class="bi bi-bar-chart-line fs-2 d-block mb-2"></i><strong>Chart Placeholder</strong><div class="small mt-1">พร้อมรับข้อมูลจริงและชนิดแผนภูมิในอนาคต</div></div></div></div></article></div><div class="col-lg-6"><article class="card monitor-widget h-100"><div class="card-header py-3 px-4"><h3 class="page-heading h5 fw-bold mb-0">พื้นที่แผนภูมิเพิ่มเติม</h3></div><div class="card-body"><div class="chart-placeholder"><div><i class="bi bi-pie-chart fs-2 d-block mb-2"></i><strong>Flexible Widget Area</strong><div class="small mt-1">พร้อมรองรับวิดเจ็ตข้อมูลในอนาคต</div></div></div></div></article></div></div><details class="card monitor-widget additional-information"><summary class="card-header d-flex align-items-center py-3 px-4"><span class="section-icon d-inline-flex align-items-center justify-content-center me-2"><i class="bi bi-plus-circle"></i></span><span class="page-heading h5 fw-bold">ส่วนที่เพิ่มเติมในอนาคต</span></summary><div class="card-body text-muted"></div></details></section>
<section class="card table-card"><div class="card-header d-flex align-items-center justify-content-between py-3 px-4"><div><h2 class="h5 mb-1 fw-bold page-heading">งานล่าสุด</h2><p class="text-muted small mb-0">ข้อมูลล่าสุดจากฐานข้อมูล</p></div><a class="btn btn-primary btn-sm px-3" href="../report/"><i class="bi bi-list-check me-1"></i>ดูทั้งหมด</a></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th class="ps-4 py-3">หัวข้องาน</th><th>แผนก</th><th>สถานะ</th><th class="pe-4">วันที่</th></tr></thead><tbody><?php if ($recent_tasks->num_rows === 0): ?><tr><td colspan="4" class="text-center text-muted py-4">ยังไม่มีข้อมูลงาน</td></tr><?php else: ?><?php while ($task = $recent_tasks->fetch_assoc()): ?><?php [$label, $class] = dashboard_status_meta($task["status"]); ?><tr><td class="ps-4 fw-semibold"><?php echo htmlspecialchars($task["title"], ENT_QUOTES, "UTF-8"); ?></td><td><?php echo htmlspecialchars($task["department"], ENT_QUOTES, "UTF-8"); ?></td><td><span class="badge rounded-pill <?php echo $class; ?>"><?php echo $label; ?></span></td><td class="pe-4"><?php echo date("d/m/", strtotime($task["created_at"])) . (date("Y", strtotime($task["created_at"])) + 543); ?></td></tr><?php endwhile; ?><?php endif; ?></tbody></table></div></section></main></div>
<script>
    // Real, permission-scoped latest tasks supplied by the server.
    const dashboardLatestTasks = <?php echo json_encode($recent_task_rows, JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT); ?>;

    window.addEventListener('load', () => {
        const card = document.querySelector('.table-card');
        if (!card) return;
        const escapeHtml = (value) => String(value ?? '').replace(/[&<>'"]/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#039;', '"': '&quot;' }[character]));
        const thaiDate = (value) => {
            const date = new Date(value.replace(' ', 'T'));
            return new Intl.DateTimeFormat('th-TH-u-ca-buddhist', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false }).format(date) + ' น.';
        };
        const statusMeta = (status) => ({ pending: ['รอดำเนินการ', 'status-pending'], in_progress: ['กำลังดำเนินการ', 'status-progress'], completed: ['เสร็จสิ้น', 'status-completed'], cancelled: ['ยกเลิก', 'status-cancelled'] }[status] || [status, 'status-pending']);
        const rows = dashboardLatestTasks.map((task) => {
            const [label, className] = statusMeta(task.status);
            return `<tr><td class="ps-4 fw-semibold">#T-${String(task.id).padStart(5, '0')}</td><td>${thaiDate(task.created_at)}</td><td><button class="btn btn-link p-0 text-start fw-semibold text-decoration-none dashboard-task-detail" data-task-id="${task.id}">${escapeHtml(task.title)}</button></td><td>${escapeHtml(task.department)}</td><td><span class="badge rounded-pill ${className}">${label}</span></td><td class="pe-4">${escapeHtml(task.created_by_name)}</td></tr>`;
        }).join('') || '<tr><td colspan="6" class="text-center text-muted py-4">ยังไม่มีข้อมูลงาน</td></tr>';
        card.innerHTML = `<div class="card-header d-flex align-items-center justify-content-between py-3 px-4"><div><h2 class="h5 mb-1 fw-bold page-heading">งานล่าสุด</h2><p class="text-muted small mb-0">ข้อมูลล่าสุดจากฐานข้อมูล</p></div><a class="btn btn-primary btn-sm px-3" href="../report/"><i class="bi bi-list-check me-1"></i>ดูทั้งหมด</a></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th class="ps-4 py-3">รหัสงาน</th><th>วันที่สร้าง</th><th>หัวข้องาน</th><th>แผนก</th><th>สถานะ</th><th class="pe-4">ผู้สร้าง</th></tr></thead><tbody>${rows}</tbody></table></div>`;

        card.querySelectorAll('.dashboard-task-detail').forEach((button) => button.addEventListener('click', () => {
            const task = dashboardLatestTasks.find((item) => Number(item.id) === Number(button.dataset.taskId));
            if (!task) return;
            const [label, className] = statusMeta(task.status);
            const existingModal = document.getElementById('dashboardTaskDetailModal');
            if (existingModal) existingModal.remove();
            const modal = document.createElement('div');
            modal.className = 'modal fade'; modal.id = 'dashboardTaskDetailModal'; modal.tabIndex = -1;
            modal.innerHTML = `<div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h2 class="modal-title fs-5">รายละเอียดงาน #T-${String(task.id).padStart(5, '0')}</h2><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-6"><strong>หัวข้องาน:</strong> ${escapeHtml(task.title)}</div><div class="col-md-3"><strong>แผนก:</strong> ${escapeHtml(task.department)}</div><div class="col-md-3"><strong>สถานะ:</strong> <span class="badge ${className}">${label}</span></div><div class="col-md-6"><strong>ประเภทปัญหา:</strong> ${escapeHtml(task.category)}</div><div class="col-md-6"><strong>สถานที่:</strong> ${escapeHtml(task.location)}</div><div class="col-12"><strong>รายละเอียดปัญหา:</strong><div class="mt-1">${escapeHtml(task.problem).replace(/\n/g, '<br>')}</div></div><div class="col-12"><strong>วิธีแก้ไข:</strong><div class="mt-1">${escapeHtml(task.solution).replace(/\n/g, '<br>')}</div></div><div class="col-md-6"><strong>เวลาเริ่ม:</strong> ${thaiDate(task.start_time)}</div><div class="col-md-6"><strong>เวลาสิ้นสุด:</strong> ${thaiDate(task.finish_time)}</div><div class="col-12"><strong>หมายเหตุ:</strong> ${escapeHtml(task.remark).replace(/\n/g, '<br>')}</div><div class="col-md-6"><strong>ผู้สร้าง:</strong> ${escapeHtml(task.created_by_name)}</div><div class="col-md-6"><strong>สร้างเมื่อ:</strong> ${thaiDate(task.created_at)}</div><div class="col-md-6"><strong>อัปเดตเมื่อ:</strong> ${thaiDate(task.updated_at)}</div></div></div><div class="modal-footer"><a class="btn btn-primary" href="../report/?edit=${task.id}">Edit Task</a><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">ปิด</button></div></div></div>`;
            document.body.appendChild(modal);
            new bootstrap.Modal(modal).show();
        }));
    });
</script>
